<?php
namespace App\\Models;use Illuminate\\Database\\Eloquent\\Model;use Illuminate\\Database\\Eloquent\\Relations\\{BelongsTo,HasMany};class Product extends Model{protected $fillable=['category_id','name','slug','description','image','price_usd','price_cdf','stock','is_active','condition'];protected function casts():array{return ['price_usd'=>'decimal:2','price_cdf'=>'decimal:2','is_active'=>'boolean'];}public function category():BelongsTo{return $this->belongsTo(Category::class);}public function reviews():HasMany{return $this->hasMany(Review::class);}public function price(string $currency):string{return (string)($currency==='CDF'?$this->price_cdf:$this->price_usd);}}
